            frame_step_s?: number;
            /** @description Niveau en dB de la couleur la plus sombre (bas de la légende) ; tout ce qui est plus faible a cette couleur. */
            db_min?: number;
            /** @description Niveau en dB de la couleur la plus claire (haut de la légende) ; tout ce qui est plus fort a cette couleur. */
